export interface NLPModuleItem {
  id: string
  categoryId: number // 1 - 31
  categoryName: string
  name: string
  description: string
  inputModes: ('text' | 'file' | 'voice')[]
  defaultPrompt: string
  sampleInput: string
  accuracy: string
  pipelineSteps: string[]
  capabilities: string[]
  databaseTable: string
  apiEndpoint: string
  icon: string
}

export interface NLPCategory {
  id: number
  name: string
  description: string
  icon: string
}

