  addProj(5, c5, "qa-pdf", "PDF Question Answering", "Ask natural language questions against uploaded PDF documents.", "Answer user query using exact citations retrieved from the uploaded PDF document.", "What is the total revenue reported on page 14 of the quarterly report?", ["PDF Text Extraction", "Vector Retrieval", "Grounded QA Synthesis"], ["PDF Chat", "RAG", "Doc QA"], "tbl_qa_pdf_logs", "FileText")
